select json_build_object('card_visits_rls',(select relrowsecurity from pg_class where oid='public.work_card_visits'::regclass),'own_person_policies',(select count(*)=3 from pg_policies where schemaname='public' and tablename='work_card_visits' and coalesce(qual,with_check) like '%auth.uid()%'),'visit_timestamp_trigger',exists(select 1 from pg_trigger where tgname='stamp_card_visit' and not tgisinternal));
